     1	// The storage key grammar, alone in its own module on purpose.
     2	//
     3	// The production payload decoder (protocol-client) must validate storage keys,
     4	// so whatever module it imports this from is in every resuming page's eager
     5	// chunk. The rest of the storage surface — the slot symbol, the slot-entry key
     6	// derivation, the no-flash attribute name — is client-storage-only and is
     7	// demand-loaded with the storage plane. Keeping them in one module put all of
     8	// it in the eager chunk, because a lazy chunk importing from an eager module
     9	// pins that module's exports there.
    10	//
    11	// A storage key is either an author's verbatim explicit key or a derived
    12	// markless:<identifier>. Permissive but structurally safe: letters, digits, and
    13	// $ _ : . - only (no whitespace, quotes, brackets, or control characters). The
    14	// colon admits the markless: namespace; the resume decoder uses this to reject
    15	// malformed payloads.
    16	const STORAGE_KEY_PATTERN = /^[A-Za-z0-9$_:.-]+$/;
    17	
    18	export function isValidStorageKey(value: string): boolean {
    19		return STORAGE_KEY_PATTERN.test(value);
    20	}
